function compute_digest(reg_type, reg_val):
  if reg_type == INT:
    // 64-bit integer value
    trailing_zeros = count_trailing_zeros(reg_val) & 0x3F // [assumed: count trailing zeros capped at 63]
    leading_zeros  = count_leading_zeros(reg_val)  & 0x3F // [assumed: count leading zeros capped at 63]
    val_lsb        = reg_val & 0x3F
    digest = (trailing_zeros) ^ (leading_zeros << 3) ^ (val_lsb << 6)
    return digest & 0xFFF // 12 bits
  else if reg_type == FP:
    // Floating point format inspection (FP64, FP32, FP16)
    // [assumed: right-aligned at bit position 3]
    if is_fp64(reg_val):
      // Val[63:55]: sign bit (bit 63) + 8 exponent bits (bits 62:55) -> digest[11:3]
      return ((reg_val >> 55) & 0x1FF) << 3
    else if is_fp32(reg_val):
      // Value[31:26]: sign bit (bit 31) + 5 exponent bits (bits 30:26) -> digest[8:3]
      return ((reg_val >> 26) & 0x3F) << 3
    else if is_fp16(reg_val):
      // Val[15:13]: sign bit (bit 15) + 2 exponent bits (bits 14:13) -> digest[5:3]
      return ((reg_val >> 13) & 0x07) << 3
    else:
      return 0
  else if reg_type == FLAG:
    // 4 condition code flags replicated 3 times
    flag4 = reg_val & 0x0F
    return (flag4 << 8) | (flag4 << 4) | flag4
  return 0

function on_decode(inst):
  // 1. Advance decay counter for all valid register digests
  for r in 0..64:
    if reg_status_table[r].valid == 1:
      if reg_status_table[r].decay_ctr == 255:
        reg_status_table[r].valid = 0 // Invalidate stale digest after 256 instructions
      else:
        reg_status_table[r].decay_ctr += 1

  // 2. If instruction writes destination register dest_reg:
  if inst.writes_reg:
    d = inst.dest_reg // in range 0..64
    reg_status_table[d].valid = 0
    reg_status_table[d].payload = inst.rob_index & 0x3FFF // store 14-bit ROB tag
    reg_status_table[d].decay_ctr = 0

function on_instruction_complete(rob_index, dest_reg, result_val, reg_type):
  if dest_reg in 0..64:
    if reg_status_table[dest_reg].valid == 0 and reg_status_table[dest_reg].payload == (rob_index & 0x3FFF):
      digest = compute_digest(reg_type, result_val)
      reg_status_table[dest_reg].payload = digest & 0xFFF // store 12-bit digest
      reg_status_table[dest_reg].valid = 1
      reg_status_table[dest_reg].decay_ctr = 0

function predict_sR(PC):
  sR_sum = 0
  // Process each of the 8 banks independently
  for bank_id in 0..7:
    // Bank registers: r where (r % 8 == bank_id), r in 0..64
    // Bank 0 has 9 registers; Banks 1-7 have 8 registers
    bank_regs = [r for r in 0..64 if (r % 8 == bank_id)]

    // Determine which registers currently have valid digests
    available_regs = [r for r in bank_regs if reg_status_table[r].valid == 1]

    if len(available_regs) == 0:
      continue // Bank contributes 0 if no registers have valid digests

    // Look up usefulness vector for registers in this bank
    ut_idx0 = hash_UT(PC, 0) % 8
    ut_idx1 = hash_UT(PC, 1) % 8
    ut_idx2 = hash_UT(PC, 2) % 8

    best_reg = -1
    max_usefulness = -1000
    for r in available_regs:
      u = sR_UT[bank_id].UT0[ut_idx0][r] + sR_UT[bank_id].UT1[ut_idx1][r] + sR_UT[bank_id].UT2[ut_idx2][r]
      if u > max_usefulness:
        max_usefulness = u
        best_reg = r

    // Lookup prediction weight tables for best_reg
    digest = reg_status_table[best_reg].payload & 0xFFF
    h0 = hash(PC, digest, 0) % 512
    h1 = hash(PC, digest, 1) % 256
    h2 = hash(PC, digest, 2) % 128

    bank_sum = sR_WT[bank_id].WT0[h0] + sR_WT[bank_id].WT1[h1] + sR_WT[bank_id].WT2[h2]

    // Scale bank contribution: x2.5 if bank usefulness is positive, else x0
    if max_usefulness > 0:
      scaled_bank_sum = bank_sum * 2.5 // [assumed: fixed-point / integer 2.5x scaling]
    else:
      scaled_bank_sum = 0

    sR_sum += scaled_bank_sum

  return sR_sum

function update_sR(PC, actual_outcome, pred_info, train_wt, train_ut):
  // train_wt is true if prediction was incorrect or |LSUM| <= update_threshold
  for bank_id in 0..7:
    available_regs_at_pred = pred_info.available_regs[bank_id]
    if len(available_regs_at_pred) == 0:
      continue

    // Section 4.2: If several registers were available, randomly select one for the update
    r_upd = randomly_select(available_regs_at_pred)

    ut_idx0 = hash_UT(PC, 0) % 8
    ut_idx1 = hash_UT(PC, 1) % 8
    ut_idx2 = hash_UT(PC, 2) % 8

    digest = pred_info.reg_digests[r_upd]
    h0 = hash(PC, digest, 0) % 512
    h1 = hash(PC, digest, 1) % 256
    h2 = hash(PC, digest, 2) % 128

    // 1. Update Weight Tables (WT)
    if train_wt:
      delta = (actual_outcome == TAKEN) ? +1 : -1
      sR_WT[bank_id].WT0[h0] = sat_add(sR_WT[bank_id].WT0[h0], delta, -32, 31)
      sR_WT[bank_id].WT1[h1] = sat_add(sR_WT[bank_id].WT1[h1], delta, -32, 31)
      sR_WT[bank_id].WT2[h2] = sat_add(sR_WT[bank_id].WT2[h2], delta, -32, 31)

    // 2. Update Usefulness Tables (UT)
    if train_ut:
      reg_bank_sum = sR_WT[bank_id].WT0[h0] + sR_WT[bank_id].WT1[h1] + sR_WT[bank_id].WT2[h2]
      pred_sign = (reg_bank_sum >= 0) ? TAKEN : NOT_TAKEN
      u_delta = (pred_sign == actual_outcome) ? +1 : -1
      sR_UT[bank_id].UT0[ut_idx0][r_upd] = sat_add(sR_UT[bank_id].UT0[ut_idx0][r_upd], u_delta, -32, 31)
      sR_UT[bank_id].UT1[ut_idx1][r_upd] = sat_add(sR_UT[bank_id].UT1[ut_idx1][r_upd], u_delta, -32, 31)
      sR_UT[bank_id].UT2[ut_idx2][r_upd] = sat_add(sR_UT[bank_id].UT2[ut_idx2][r_upd], u_delta, -32, 31)

function on_pipeline_flush(squashed_rob_indices):
  for r in 0..64:
    // If register was in-flight and squashed before completion, revert to invalid
    if reg_status_table[r].valid == 0 and (reg_status_table[r].payload in squashed_rob_indices):
      // [assumed: clear tag or mark invalid until next architectural commit / producer]
      reg_status_table[r].decay_ctr = 255
